@property
def statement_type(self) -> str:
    ddl_statements = ("ALTER", "CREATE", "DROP")
    dml_statements = ("SELECT", "INSERT", "UNLOAD", "UPDATE", "DELETE")
    first_word = (self.query or "").strip().split(" ")[0].upper()
    if first_word in ddl_statements:
        return "DDL"
    elif first_word in dml_statements:
        return "DML"
    else:
        return "UTILITY"
